scwin.fn_tab1_Search = function() {
    var vISUR_CD_tab1 = $c.stf.getObjectValue(txb_tab1_ISUR_CD);
    var vLIST_STAT_CD_tab1 = $c.stf.getObjectValue(chb_tab1_LIST_STAT_CD);
