    var vIBAS_YYYY_tab1 = $c.stf.getObjectValue(cmb_tab1_BAS_YYYY);
    var url = "/ListedCompany.do?method=listCompanyPersonInCharge";
    url += "&ISUR_CD=" + vISUR_CD_tab1;
    url += "&LIST_STAT_CD=" + vLIST_STAT_CD_tab1;
    url += "&DEP_CD=" + vDEP_CD_tab1;
    url += "&EMP_NO=" + vEMP_NO_tab1;
    url += "&STD_INDTP=" + vISTD_INDTP_tab1;
    url += "&BAS_YYYY=" + vIBAS_YYYY_tab1;
    url += "&MKT_ID=" + js_market;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    //alert(url);
    dts_Grid_Tab1.DataID = encodeURI(url);
    dts_Grid_Tab1.Reset();
    $c.cm.ShowWin(grd_Grid);
};
