scwin.fn_read_tab1 = async function(GridID, row, colid) {
    //작업해야함 
    var objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..		
    var CMD = "R";
    if (row < 1) return;

    //OPEN 
    if (colid == "COM_NM") {
        //상세화면 
        var vISUR_CD = objDataID.getCellData(row, "ISUR_CD");
        var vCOM_NM = objDataID.getCellData(row, "COM_NM");
        var url = "/issueinfo/ULDSTF30608.gfm?";
        url += "ISUR_CD=" + vISUR_CD;
        url += "&COM_NM=" + vCOM_NM;
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        if (scwin.fn_setParam(CMD, vISUR_CD, vCOM_NM)) // formal arguments

        {
            //frame.CreateDialogFrame("child01", "/issueinfo/ULDSTF30608.gfm", "공시담당자 이력조회", 200, 10, 810,740, "window");	
            $c.frame.path("../../").GWinOpen("ULDSTF30608", url, "공시담당자 이력조회", 10, 20, 810, 740, "");
        }
    }
    if (colid == "CHRG_TP_CDNM") {
        //공시담당연락처 변경 
        var vISUR_CD = objDataID.getCellData(row, "ISUR_CD");
        var vCOM_NM = objDataID.getCellData(row, "COM_NM");
        if (scwin.fn_setParam(CMD, vISUR_CD, vCOM_NM)) // formal arguments

        {
            await $c.frame.CreateDialogFrame("child01", "/issueinfo/ULDSTF30604.gfm", "공시담당자 연락처변경", 200, 100, 770, 400, "window");
        }
    }
};
scwin.fn_read_tab2 = function(GridID, row, colid) {
    //작업해야함 
    var objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..		
    var CMD = "R";
    if (row < 1) return;

    //OPEN 
    if (colid == "COM_NM") {
        //상세화면 
        var vISUR_CD = objDataID.getCellData(row, "ISUR_CD");
        var vCOM_NM = objDataID.getCellData(row, "COM_NM");
        var vSTKCERT_LIST_DD = objDataID.getCellData(row, "STKCERT_LIST_DD");
        var url = "/issueinfo/ULDSTF30606.gfm?";
        url += "ISUR_CD=" + vISUR_CD;
        url += "&COM_NM=" + vCOM_NM;
        url += "&STKCERT_LIST_DD=" + vSTKCERT_LIST_DD;
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        if (scwin.fn_setParam(CMD, vISUR_CD, vCOM_NM, vSTKCERT_LIST_DD)) // formal arguments

        {
            //frame.CreateDialogFrame("child01", "/issueinfo/ULDSTF30606.gfm", "세부교육이수현황", 10, 10, 1000, 850, "window");
            $c.frame.path("../../").GWinOpen("child01", url, "세부교육이수현황", 10, 20, 990, 770, "");
        }
    }
};
scwin.fn_setParam = function() {
    // child에 param을 넘긴다.
    if (typeof(scwin.gParamObj) == "undefined") {
        $c.win.alert("전역변수 gParamObj를 선언하세요.");
        return false;
    }
    var argv = fn_setParam.arguments;
    var argc = fn_setParam.arguments.length;
    scwin.gParamObj = new Array(argc); // 초기화
    for (var i = 0; i < argc; i++) // actual arguments

    {
        eval("gParamObj.param" + i + " = argv[" + i + "]");
    }
    return true;
};


//관리자 기능
scwin.fn_Save = function() {
    var complt_dd = $c.stf.getObjectValue(edt_TAB4_COMPLT_DD);
    var kind_cd = $c.stf.getObjectValue(cmb_tab4_EDU_KIND_CD);
    var edu_nm = $c.stf.getObjectValue(txb_tab4_DISCLS_EDU_CRS_NM);
    var file_nm = $c.stf.getObjectValue(txb_ATTACH_FILE_NM);
    var msg = "";
    if (complt_dd == "") {
        msg = $c.stf.getMessageParam("MSG-A005", "교육일자");
        $c.win.alert(msg);
        edt_TAB4_COMPLT_DD.focus();
        return;
    }
    if (kind_cd == "") {
        msg = $c.stf.getMessageParam("MSG-A005", "교육구분");
        $c.win.alert(msg);
        cmb_tab4_EDU_KIND_CD.focus();
        return;
    }
    if (edu_nm == "") {
        msg = $c.stf.getMessageParam("MSG-A005", "교육과정명");
        $c.win.alert(msg);
        txb_tab4_DISCLS_EDU_CRS_NM.focus();
        return;
    }
    if (file_nm == "") {
        msg = $c.stf.getMessageParam("MSG-A005", "파일");
        $c.win.alert(msg);
        txb_ATTACH_FILE_NM.focus();
        return;
    }
    var res = window.confirm("[저장]하시겠습니까?");
    if (res) {
        scwin.LastJob = "저장";
        trs_Save.Action = "/ListedCompany.do?method=registerCompanyPersonInChargeAdmFile" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInputMaster=dts_Tab4_SheEmail,I:pFile=dts_FileList)";
        trs_Save.post();
    }
};




//관리자 기능
scwin.fn_SelectAttach = function() {
    if (file.getValue() == "") return;
    txb_ATTACH_FILE_NM.setValue(file.getValue());
    dts_FileList.setCellData(1, "fileInfo", file.getValue());
    dts_FileList.setCellData(1, "fileUrl", file.getValue());
};
scwin.fn_SendMail = function() {
    var email = $c.stf.getObjectValue(txb_tab4_EMAIL);
    var name = $c.stf.getObjectValue(txb_tab4_TARGTNAME);
    var contents = $c.stf.getObjectValue(txa_tab4_TARGTCONTENT);
    var msg = "";
    if (email == "") {
        msg = $c.stf.getMessageParam("MSG-A005", "이메일");
        $c.win.alert(msg);
        txb_tab4_EMAIL.focus();
        return;
    }
    if ($c.stf.IsValidEmail(email) == false) {
        $c.win.alert("[이메일] 정확하지 않습니다.");
        txb_tab4_EMAIL.focus();
        return;
    }
    if (name == "") {
        msg = $c.stf.getMessageParam("MSG-A005", "받는이");
        $c.win.alert(msg);
        txb_tab4_TARGTNAME.focus();
        return;
    }
    if ($c.stf.checkMaxLength(txb_tab4_TARGTNAME, 100, "받는이") == false) {
        return;
    }
    if (contents == "") {
        msg = $c.stf.getMessageParam("MSG-A005", "안내내용");
        $c.win.alert(msg);
        txa_tab4_TARGTCONTENT.focus();
        return;
    }
    if ($c.stf.checkMaxLength(txa_tab4_TARGTCONTENT, 2000, "안내내용") == false) {
        return;
    }
    var res = window.confirm("[메일]을 전송하시겠습니까?");
    if (res) {
        scwin.LastJob = "메일전송";
        trs_Save.Action = "/ListedCompany.do?method=sendEmail" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInputMaster=dts_Tab4_SheEmail)";
        trs_Save.post();
    }
};
scwin.MxTab_1_OnSelChanged = function(nIndex) {
    if (nIndex == '1') {
        scwin.gIndex = nIndex;
        $c.stf.showObj(btn_Excel, true);
        $c.stf.showObj(panel_page, true);
    } else if (nIndex == '2') {
        scwin.gIndex = nIndex;
        $c.stf.showObj(btn_Excel, true);
        $c.stf.showObj(panel_page, true);
    } else if (nIndex == '3') {
        scwin.gIndex = nIndex;
        $c.stf.showObj(btn_Excel, true);
        $c.stf.showObj(panel_page, true);
    } else {
        $c.stf.showObj(btn_Excel, false);
        $c.stf.showObj(panel_page, false);
    }
};
scwin.dts_Grid_Tab1_OnLoadCompleted = function(rowcount) {
    var totalcnt = dts_Grid_Tab1.getCellData(rowcount, "RNUM");
    $c.stf.FillGridHeaderTotalCnt(totalcnt, panel_page);
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.dts_Grid_Tab1_OnLoadError = function() {
    $c.stf.alert_error(dts_Grid_Tab1);
};
scwin.dts_Grid_Tab2_OnLoadCompleted = function(rowcount) {
