scwin.btn_tab1_Search_onclick = function() {
    scwin.fn_tab1_Search();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    if (scwin.gIndex == '1') {
        $c.data.downloadGridViewExcel(grd_Grid, "기업담당자 목록검색", "", "8");
    } else if (scwin.gIndex == '2') {
        grd_Grid2.GridToExcel("교육이수현황목록검색", "", "8");
    } else if (scwin.gIndex == '3') {
        grd_Grid3.GridToExcel("교육일정목록검색", "", "8");
    }
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    scwin.fn_read_tab1(grd_Grid, row, colid);
};
scwin.trs_Save_OnFail = function() {
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = function() {
    /*
    	cmb_tab4_EDU_KIND_CD.Text="";
    	edt_TAB4_COMPLT_DD.Text="";
    	txb_tab4_DISCLS_EDU_CRS_NM.value="";
    	txb_ATTACH_FILE_NM.value="";
    	dts_FileList.Reset();
    */

    var msg = $c.stf.getMessageParam("MSG-A001", scwin.LastJob);
    $c.win.alert(msg);
    dts_Tab4_SheEmail.removeAll();
    dts_FileList.removeAll();
    dts_Tab4_SheEmail.insertRow();
    dts_FileList.insertRow();
};
scwin.btn_ISUR_CD_onclick = function() {
    // IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
